def catalog():
    rows=[]
    for source,skills in [('agent-ml-skills',ML),('data-analytics-skills',ANALYTICS)]:
        for skill in skills:
            key,scenario=MAP[skill];title,slug,purpose=DATASETS[key];rows.append({'skill':skill,'source':source,'category':category(skill),'dataset':title,'kaggle_slug':slug,'dataset_purpose':purpose,'scenario':scenario})
    return rows
def category(skill):
    if skill in ML:return 'ML & MLOps'
    groups=[('Quality & validation',ANALYTICS[:5]),('Documentation & knowledge',ANALYTICS[5:10]),('Analysis & investigation',ANALYTICS[10:17]),('Storytelling & visualization',ANALYTICS[17:22]),('Stakeholder communication',ANALYTICS[22:27]),('Workflow optimization',ANALYTICS[27:])]
    return next(n for n,x in groups if skill in x)
